INSERT INTO `chapter_blocks` (`block_id`, `chapter_id`, `type`, `content`, `sort_order`, `created_at`) VALUES
(1, 1, 'narration', 'Pertama kali kami bertemu kami sangat senang sekali. cerita ini dimulai dari semua orang yang bersusah payah menggapai mimpinya.', 0, '2026-05-21 11:24:51'),
(5, 4, 'narration', 'Aku seorang kapitern', 0, '2026-05-21 12:21:08'),
(6, 5, 'narration', 'AAAAAAAAAAAAAAAAAAAA', 0, '2026-05-21 12:29:15'),
(10, 1, 'roomchat', '', 2, '2026-05-21 13:17:38'),
(14, 7, 'narration', 'Pagi itu, ruang kelas Teknik Informatika 3A sudah terasa seperti medan perang.\nBelum dosennya datang, belum tugasnya dibahas, tapi delapan mahasiswi ini sudah membuat suasana ribut seperti forum chat yang kebanyakan notifikasi.\n\nMeisya duduk paling depan dengan wajah tenang, tapi tangannya sudah sibuk membuka laptop.\nAlin masih setengah sadar, menatap layar kosong seperti sedang mempertanyakan tujuan hidup.\nNia sibuk cek tugas orang lain, Kadiva mengeluh karena belum sarapan, Ara panik mencari file, Echa ketawa sendiri tanpa alasan jelas, Jeje pura-pura paham padahal tidak, dan Naya paling kecil di antara mereka justru paling berisik.\n\nHari itu seharusnya cuma kelas biasa.\nTapi seperti biasa, “biasa” tidak pernah berlaku untuk anak-anak Moju.', 0, '2026-05-29 13:45:44'),
(16, 7, 'roomchat', '', 2, '2026-05-29 13:45:44'),
(18, 8, 'narration', 'Hari itu, Meisya, Alin, Nia, Kadiva, Ara, Echa, Jeje, dan Naya berkumpul seperti biasa di taman kota setelah menjalani aktivitas masing-masing. Awalnya, mereka hanya mengobrol santai dan bercanda seperti biasanya, sampai Ara menemukan sebuah kotak kayu tua yang tersembunyi di balik semak-semak. Karena penasaran, mereka membukanya dan menemukan sebuah surat serta peta kuno yang berisi petunjuk tentang Buku Sakti Moju, sebuah buku legendaris yang konon mampu mengubah nasib siapa pun yang berhasil menemukannya. Mereka menganggapnya sebagai lelucon sampai peta tersebut tiba-tiba memancarkan cahaya keemasan dan memperlihatkan jalur yang sebelumnya tidak ada. Sejak saat itu, kedelapan sahabat tersebut mulai menyadari bahwa mereka mungkin baru saja menemukan sesuatu yang akan mengubah hidup mereka selamanya.', 0, '2026-05-30 13:51:37'),
(20, 8, 'roomchat', '', 3, '2026-05-30 13:51:58'),
(21, 8, 'roomchat', '', 3, '2026-05-30 14:26:07'),
(22, 9, 'narration', 'ini adalah hari pertama ospek as maba', 0, '2026-05-30 16:13:39'),
(24, 9, 'roomchat', '', 5, '2026-05-30 16:13:39');

